mapper.select:
select
    id,equipment_id,equipment_name,equipment_code,breakdown_id,breakdown_name,breakdown_description,breakdown_image,apply_time,apply_by,repair_time,repair_by,repair_method,approve_by,status,is_knowledge,review,is_deleted,version,create_by,create_time,update_by,update_time,attr1,attr2,attr3,approve_time
from eq_repair_report

    is_deleted = 0
     and id = #{id}
     and equipment_id = #{equipmentId}
     and equipment_name = #{equipmentName}
     and equipment_code = #{equipmentCode}
     and breakdown_id = #{breakdownId}
     and breakdown_name = #{breakdownName}
     and breakdown_description like concat('%', #{breakdownDescription},'%')
     and breakdown_image = #{breakdownImage}
     and apply_time = #{applyTime}
     and apply_by = #{applyBy}
     and repair_time = #{repairTime}
     and repair_by = #{repairBy}
     and repair_method like concat('%', #{repairMethod},'%')
     and approve_by = #{approveBy}
     and status = #{status}
     and is_knowledge = #{isKnowledge}
     and review = #{review}
     and is_deleted = #{isDeleted}
     and version = #{version}
     and create_by = #{createBy}
     and create_time = #{createTime}
     and update_by = #{updateBy}
     and update_time = #{updateTime}
     and attr1 = #{attr1}
     and attr2 = #{attr2}
     and attr3 = #{attr3}
     and approve_time = #{approveTime}

        AND date_format(apply_time,'%y%m%d') >= date_format(#{params.beginTime},'%y%m%d')


        AND date_format(apply_time,'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')


    ${params.dataScope}

order by status asc, apply_time desc

mapper.update:
update eq_repair_report
equipment_id = #{equipmentId}, equipment_name = #{equipmentName}, equipment_code = #{equipmentCode}, breakdown_id = #{breakdownId}, breakdown_name = #{breakdownName}, breakdown_description = #{breakdownDescription}, breakdown_image = #{breakdownImage}, apply_time = #{applyTime}, apply_by = #{applyBy}, repair_time = #{repairTime}, repair_by = #{repairBy}, repair_method = #{repairMethod}, approve_by = #{approveBy}, status = #{status}, is_knowledge = #{isKnowledge}, review = #{review}, is_deleted = #{isDeleted}, version = #{version}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, attr1 = #{attr1}, attr2 = #{attr2}, attr3 = #{attr3}, approve_time = #{approveTime},
where id = #{id} and version = #{version}

